 for refl in [False,True]:
  for rot in range(4):
   pts=[]; maps=[]
   for rr,cc in S:
    r,c=rr,cc
    if refl: c=-c
    for _ in range(rot): r,c=c,-r
    pts.append((r,c)); maps.append(((r,c),(rr,cc)))
   mr=min(r for r,c in pts); mc=min(c for r,c in pts)
   normalized=frozenset((r-mr,c-mc) for r,c in pts)
   if normalized not in [x[0] for x in out]: out.append((normalized,{(r-mr,c-mc):(rr,cc) for (r,c),(rr,cc) in maps}))
 return out
